  "aktywnosci": [
    {
      "tytul": "Wróżby z cieni i lampioniki",
      "opis": "Nauczyciel gasi światło i zapala małą lampkę lub świeczkę LED; dzieci obserwują cienie dłoni na ścianie i zgadują, co przedstawiają. Następnie każde dziecko ozdabia papierowy lampion (z gotowej bibuły lub wyciętego kartonu) naklejając kolorowe gwiazdki, serduszka i inne wzory. Lampioniki można postawić na parapecie jako dekorację."
    },
    {
      "tytul": "Magiczne kubeczki – zabawy z rytmem",
      "opis": "Dzieci siedzą w kole, każde ma przed sobą plastikowy kubeczek. Nauczyciel wystukuje prosty rytm (np. pukanie w kubek, przesuwanie go po podłodze), a dzieci naśladują. Potem nauczyciel chowa pod jednym kubkiem mały przedmiot (np. kasztan) i dzieci zgadują, pod którym jest – to zabawa w „wróżenie” bez używania słowa los."
    },
    {
      "tytul": "Andrzejkowe serduszka z gliny",
      "opis": "Dzieci otrzymują kawałek masy solnej lub modeliny i formują serduszko – symbol andrzejkowych wróżb. Nauczyciel pokazuje, jak odcisnąć w glinie wzór patyczkiem lub pieczątką z liścia. Po wyschnięciu serduszka można pomalować i zabrać do domu – to pamiątka po wspólnej zabawie."
    }
  ]
}
